export type CatalogPageId = 'productCategories' | 'products' | 'priceLists'
type Snapshot = { catalog: CatalogState; archives: ArchiveState; customers: CustomerState }
type Context = Snapshot & { org: OrgState; scope: OrgScope | null }
const load = (tenant: string): Snapshot => ({ catalog: readCatalog(tenant), archives: readArchives(tenant), customers: readCustomers(tenant) })
const titles = { productCategories: '商品分类', products: '商品', priceLists: '价目表' }
